class Money:
    def __init__(self, amount):
        self.amount = amount

    def __repr__(self):
        return f"Money({self.amount!r})"    # for developers

    def __str__(self):
        return f"${self.amount:.2f}"         # for users

m = Money(5)
print(m)          # $5.00          — print uses __str__
print(repr(m))    # Money(5)
print([m])        # [Money(5)]     ← containers ALWAYS use __repr__ for items
print(f"{m}")     # $5.00
print(f"{m!r}")   # Money(5)

